"use strict";(self.webpackChunkrithmia=self.webpackChunkrithmia||[]).push([["6929"],{9603(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>r,contentTitle:()=>o,toc:()=>l,assets:()=>h});var n=JSON.parse('{"id":"Past Campaigns/Steampunk Campaign/Overview","title":"Steampunk campaign","description":"Could also use a different system Steampunk Heists","source":"@site/docs/Past Campaigns/Steampunk Campaign/Overview.md","sourceDirName":"Past Campaigns/Steampunk Campaign","slug":"/Past Campaigns/Steampunk Campaign/Overview","permalink":"/Rithmia/docs/Past Campaigns/Steampunk Campaign/Overview","draft":false,"unlisted":false,"editUrl":"https://github.com/TravisH18/Rithmia/tree/main/docs/docs/Past Campaigns/Steampunk Campaign/Overview.md","tags":[],"version":"current","frontMatter":{},"sidebar":"settingSidebar","previous":{"title":"Opening meeting","permalink":"/Rithmia/docs/Past Campaigns/Primagaru Miniseries/opening-meeting"},"next":{"title":"Arc 1 (Tier 1)","permalink":"/Rithmia/docs/Past Campaigns/Steampunk Campaign/tier-1"}}'),i=a(4848),s=a(8453);let r={},o="Steampunk campaign",h={},l=[{value:"Background",id:"background",level:2},{value:"Ideas",id:"ideas",level:2}];function c(e){let t={h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"steampunk-campaign",children:"Steampunk campaign"})}),"\n",(0,i.jsx)(t.p,{children:"Could also use a different system: Blades In The Dark: Steampunk Heists"}),"\n",(0,i.jsx)(t.p,{children:"Basic idea: Gothic polluted Steampunk world and early on while working for their boss the party discovers a way to recycle energy / make clean energy and is now being hunted by the fantasy CIA."}),"\n",(0,i.jsx)(t.h2,{id:"background",children:"Background"}),"\n",(0,i.jsx)(t.p,{children:"This campaign is set roughly 50 years after the end of our last campaign (the four degens) here we find our party is a group of dungeon delvers called \u201CRetrievers\u201D groups that delve into abandoned often cursed areas that at one point in the past held potent magical energy. Two elements are important in this mining. Aetherium and residuum. Aetherium is a \u201Cgod metal\u201D and a new found source of magic power. Residuum is the residual magic element left from pure aether once the \u201Celement\u201D of aether has been extracted. This leaves residuum as an unstable element and for that reason it attempts to absorb and replicate magic and there fire gets stronger over time."}),"\n",(0,i.jsx)(t.p,{children:"Residuum and Aetherium can be combined in a chamber to create a bubble feedback look. These atoms charge each other off putting out grand amounts of heat which is used to boil steam and create all the fun steampunk gadgets"}),"\n",(0,i.jsx)(t.p,{children:"The party is a group of \u201CRetrievers\u201D miners/treasure hunters/dungeon delvers that trek through areas that once held potent magical effects in search of essentially panning for residuum and Aetherium."}),"\n",(0,i.jsx)(t.p,{children:"We begin one on of the missions an elderly pink axolotl has put the party up to where one of them uncovers a secret and while Aetherium comes from mines near planar vortexes residuum has to come from used magic energy. While on this regular journey an odd creature attacks the party sending them tumbling down a corridor to a long forgotten ziggurat where a shatter gem the size of a human skull has entirely condensed into residuum, this is worth a fortune. The party will slowly discover this is a lich phylactery that has gone dormant because no souls were fed to it. A demilich could appear near it however could be interesting."}),"\n",(0,i.jsx)(t.p,{children:"Residuums godmetal ability to absorb and adapt to magical effects will eventually be used to create a clean \u201Csolar like\u201D energy source in which they constantly feed into each other (an large Aetherium gem surrounded by residuum gems will produced enough energy for the residuum to absorb enough of the solar energy to become a Aetherium isotope turning residuum back into Aetherium"}),"\n",(0,i.jsx)(t.p,{children:"Prior to this Aetherium was used to heat water into steam often with other enhancements to the system itself."}),"\n",(0,i.jsx)(t.p,{children:"Ideas"}),"\n",(0,i.jsx)(t.p,{children:"Retrievers are rampant in the sludge filled lower cities"}),"\n",(0,i.jsx)(t.p,{children:"Legends that a wish spell creates the most amount of residuum of any one spells. The uses of wish become legendary and retrievers often seek out these places specifically for Wishgems fist sized rocks or residuum that (if enchanted properly) can but used as a sort of magic resistant amulet"}),"\n",(0,i.jsx)(t.p,{children:"In the sky cities and in the steam plants they have Irish esque chimney sweeps to clear out the magical radiation between each use."}),"\n",(0,i.jsx)(t.p,{children:"Starting Adventure:"}),"\n",(0,i.jsx)(t.p,{children:'The campaign begins as the adventurers are summoned to Verdantmoor by a local lord seeking assistance with the investigation of mysterious disappearances and unrest among his people. They soon discover that an ancient artifact is responsible for these events, causing those who come into contact with it to fall into a trance-like state where they are compelled to protect it at all costs. In reality this "artifact" is a gem dragon egg and the dragon inside has very potent psionic abilities (it cannot speak but manipulates emotions and projects images/feelings)'}),"\n",(0,i.jsx)(t.p,{children:"Verdantmoor:"}),"\n",(0,i.jsx)(t.p,{children:"The local lord who hires them could be an old retired aaxolotl folk that was godwins one shot character."}),"\n",(0,i.jsx)(t.p,{children:"Level 1-5:"}),"\n",(0,i.jsx)(t.p,{children:"The adventurers must navigate the valley and uncover the source of the artifact's power while dealing with various factions vying for control over it. They will encounter goblins, bandits, and other adversaries who are also drawn to the artifact. The climax of this story arc will have the characters battling against a rival group of treasure hunters in an attempt to secure the artifact for themselves."}),"\n",(0,i.jsx)(t.p,{children:"Level 6-10:"}),"\n",(0,i.jsx)(t.p,{children:"Having secured the artifact, the adventurers discover that it is actually a key that unlocks ancient seals guarding powerful magical forces hidden deep within the Iron Spires. As they delve deeper into the mountains, they must contend with various challenges and foes, including steam-powered constructs created by a long-lost civilization. The climax of this story arc involves confronting an ageless sorcerer who seeks to use the seals' power for his own ends."}),"\n",(0,i.jsx)(t.p,{children:"Level 11-15:"}),"\n",(0,i.jsx)(t.p,{children:"With the ancient seals broken, the adventurers discover that the power released has disrupted the natural balance between magic and technology throughout Rithmia. As chaos erupts across the land, they must journey to various locations in search of answers, including a massive factory powered by steam and enchantment. The climax of this story arc sees the characters racing against time to prevent a catastrophic explosion at the heart of the factory."}),"\n",(0,i.jsx)(t.p,{children:"Level 16-20:"}),"\n",(0,i.jsx)(t.p,{children:"Having narrowly averted disaster, the adventurers learn that the disruption in magic has attracted the attention of malevolent extraplanar entities seeking to exploit Rithmia's vulnerability. As they rally allies and gather resources for a final stand, the characters must face off against these invaders in an epic battle that will determine the fate of their world. The climax of this story arc sees the adventurers confronting the mastermind behind the invasion - an ancient dragon who seeks to rule over both worlds."}),"\n",(0,i.jsx)(t.h2,{id:"ideas",children:"Ideas"}),"\n",(0,i.jsx)(t.p,{children:"Recent Magical Discovery: The magical discovery in Rithmia is a rare mineral called Etherite, which has properties similar to both raw magical energy and highly concentrated steam power. Found deep within the Iron Spires, this new resource has begun to revolutionize various aspects of life in Rithmia, such as transportation, industry, and even warfare."}),"\n",(0,i.jsx)(t.p,{children:"Etherite was discovered by a group of explorers and miners led by the ambitious engineer, Eamon Stormwind. He recognized the potential of this unique substance and quickly began experimenting with ways to harness its power for various applications. The discovery of Etherite has also attracted the attention of various factions vying for control over its production and distribution."}),"\n",(0,i.jsx)(t.p,{children:"The potential effects of Etherite on the world are vast, as it could lead to a massive shift in the balance between magic and technology. If used irresponsibly or by malevolent forces, this newfound power could result in unstable magical energies that disrupt the natural order of things, causing chaos and destruction across Rithmia. Additionally, Etherite's ability to enhance steam-powered machinery may lead to an arms race among rival nations, potentially sparking new conflicts and alliances throughout the world."}),"\n",(0,i.jsx)(t.p,{children:"Maybe our characters can be working to construct a recycled version suing residuum."})]})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453(e,t,a){a.d(t,{R:()=>r,x:()=>o});var n=a(6540);let i={},s=n.createContext(i);function r(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);